  1	import type { WikiPage } from './api'
  2	
  3	/** Maximum nesting depth for wiki pages (a top-level page is depth 1). */
  4	export const WIKI_MAX_DEPTH = 6
  5	
  6	export interface WikiTreeNode {
  7	  page: WikiPage
  8	  depth: number
  9	  children: WikiTreeNode[]
 10	}
 11	
 12	function bySiblingOrder(a: WikiPage, b: WikiPage): number {
 13	  return a.position - b.position || a.title.localeCompare(b.title)
 14	}
 15	
 16	/**
 17	 * Build a forest from a flat page list. Pages whose parent is missing from the
 18	 * list (e.g. filtered out) are promoted to the top level so nothing is hidden.
 19	 */
 20	export function buildWikiTree(pages: WikiPage[]): WikiTreeNode[] {
 21	  const ids = new Set(pages.map(p => p.id))
 22	  const childrenOf = new Map<number | null, WikiPage[]>()
 23	  for (const page of pages) {
 24	    const key = page.parent_id !== null && ids.has(page.parent_id) ? page.parent_id : null
 25	    const list = childrenOf.get(key) ?? []
 26	    list.push(page)
 27	    childrenOf.set(key, list)
 28	  }
 29	
 30	  const visited = new Set<number>()
 31	  const build = (parentId: number | null, depth: number): WikiTreeNode[] =>
 32	    (childrenOf.get(parentId) ?? [])
 33	      .filter(p => !visited.has(p.id))
 34	      .sort(bySiblingOrder)
 35	      .map(page => {
 36	        visited.add(page.id)
 37	        return { page, depth, children: build(page.id, depth + 1) }
 38	      })
 39	
 40	  return build(null, 1)
 41	}
 42	
 43	/** Ancestors of a page, ordered from the top-level page down to the direct parent. */
 44	export function getWikiAncestors(pages: WikiPage[], pageId: number): WikiPage[] {
 45	  const byId = new Map(pages.map(p => [p.id, p]))
 46	  const chain: WikiPage[] = []
 47	  let current = byId.get(pageId)?.parent_id ?? null
 48	  while (current !== null && !chain.some(p => p.id === current)) {
 49	    const parent = byId.get(current)
 50	    if (!parent) break
 51	    chain.unshift(parent)
 52	    current = parent.parent_id
 53	  }
 54	  return chain
 55	}
 56	
 57	/** IDs of every page beneath the given page (not including the page itself). */
 58	export function getWikiDescendantIds(pages: WikiPage[], pageId: number): Set<number> {
 59	  const result = new Set<number>()
 60	  const stack = [pageId]
 61	  while (stack.length) {
 62	    const id = stack.pop() as number
 63	    for (const p of pages) {
 64	      if (p.parent_id === id && !result.has(p.id)) {
 65	        result.add(p.id)
 66	        stack.push(p.id)
 67	      }
 68	    }
 69	  }
 70	  return result
 71	}
 72	
 73	/** 1-based depth of a page. */
 74	export function getWikiDepth(pages: WikiPage[], pageId: number): number {
 75	  return getWikiAncestors(pages, pageId).length + 1
 76	}
 77	
 78	/** Number of levels in the subtree rooted at the page (a leaf is 1). */
 79	export function getWikiSubtreeHeight(pages: WikiPage[], pageId: number): number {
 80	  let height = 1
 81	  for (const p of pages) {
 82	    if (p.parent_id === pageId) {
 83	      height = Math.max(height, getWikiSubtreeHeight(pages, p.id) + 1)
 84	    }
 85	  }
 86	  return height
 87	}
 88	
 89	export type WikiMoveCheck = { ok: true } | { ok: false; reason: string }
 90	
 91	/**
 92	 * Mirror of the server-side hierarchy validation so the UI can give instant
 93	 * feedback before making a request.
 94	 */
 95	export function canMoveWikiPage(pages: WikiPage[], pageId: number, newParentId: number | null): WikiMoveCheck {
 96	  const page = pages.find(p => p.id === pageId)
 97	  if (!page) return { ok: false, reason: 'Page not found' }
 98	  if (newParentId === page.parent_id) return { ok: false, reason: 'Page is already there' }
 99	  if (newParentId === null) return { ok: true }
100	  if (newParentId === pageId) return { ok: false, reason: 'A page cannot be nested under itself' }
101	  if (getWikiDescendantIds(pages, pageId).has(newParentId)) {
102	    return { ok: false, reason: 'A page cannot be nested under one of its own sub-pages' }
103	  }
104	  if (!pages.some(p => p.id === newParentId)) return { ok: false, reason: 'Parent page not found' }
105	  const resultingDepth = getWikiDepth(pages, newParentId) + getWikiSubtreeHeight(pages, pageId)
106	  if (resultingDepth > WIKI_MAX_DEPTH) {
107	    return { ok: false, reason: `Pages can be nested at most ${WIKI_MAX_DEPTH} levels deep` }
108	  }
109	  return { ok: true }
110	}
111	
112	/** Whether a new child page may be created under the given page. */
113	export function canAddWikiChild(pages: WikiPage[], parentId: number): boolean {
114	  return getWikiDepth(pages, parentId) < WIKI_MAX_DEPTH
115	}

