  1	# Nginx configuration for {{ domain }} (with SSL)
  2	
  3	# Rate limiting zones
  4	limit_req_zone $binary_remote_addr zone={{ domain | replace('.', '_') }}_api:10m rate=100r/m;
  5	limit_req_zone $binary_remote_addr zone={{ domain | replace('.', '_') }}_auth:10m rate=20r/m;
  6	
  7	# HTTP -> HTTPS redirect
  8	server {
  9	    listen 80;
 10	    listen [::]:80;
 11	    server_name {{ domain }};
 12	
 13	    # Let's Encrypt verification
 14	    location /.well-known/acme-challenge/ {
 15	        root /var/www/html;
 16	    }
 17	
 18	    # Redirect all other traffic to HTTPS
 19	    location / {
 20	        return 301 https://$server_name$request_uri;
 21	    }
 22	}
 23	
 24	# HTTPS server
 25	server {
 26	    listen 443 ssl;
 27	    listen [::]:443 ssl;
 28	    http2 on;
 29	    server_name {{ domain }};
 30	
 31	    # SSL configuration
 32	    ssl_certificate /etc/letsencrypt/live/{{ domain }}/fullchain.pem;
 33	    ssl_certificate_key /etc/letsencrypt/live/{{ domain }}/privkey.pem;
 34	    ssl_session_timeout 1d;
 35	    ssl_session_cache shared:SSL:50m;
 36	    ssl_session_tickets off;
 37	
 38	    # Modern SSL configuration
 39	    ssl_protocols TLSv1.2 TLSv1.3;
 40	    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384;
 41	    ssl_prefer_server_ciphers off;
 42	
 43	    # OCSP stapling
 44	    ssl_stapling on;
 45	    ssl_stapling_verify on;
 46	    ssl_trusted_certificate /etc/letsencrypt/live/{{ domain }}/chain.pem;
 47	
 48	    # Security headers
 49	    add_header Strict-Transport-Security "max-age=63072000" always;
 50	    add_header X-Frame-Options "SAMEORIGIN" always;
 51	    add_header X-Content-Type-Options "nosniff" always;
 52	    add_header X-XSS-Protection "1; mode=block" always;
 53	    add_header Referrer-Policy "no-referrer-when-downgrade" always;
 54	
 55	    # Logging
 56	    access_log /var/log/nginx/{{ domain }}_access.log;
 57	    error_log /var/log/nginx/{{ domain }}_error.log;
 58	
 59	    # Max upload size
 60	    client_max_body_size 10M;
 61	
 62	    # Friendly maintenance page during deployments
 63	    error_page 502 503 504 /50x.html;
 64	    location = /50x.html {
 65	        internal;
 66	        default_type text/html;
 67	        return 503 '<!DOCTYPE html><html><head><title>Updating...</title><meta http-equiv="refresh" content="5"></head><body style="font-family:system-ui;display:flex;justify-content:center;align-items:center;height:100vh;margin:0;background:#f8fafc"><div style="text-align:center"><h1 style="color:#1e293b">Updating TaskAI</h1><p style="color:#64748b">Please wait a moment, this page will refresh automatically.</p></div></body></html>';
 68	    }
 69	
 70	    # Auth endpoints (stricter rate limiting)
 71	    location ~ ^/api/auth {
 72	        limit_req zone={{ domain | replace('.', '_') }}_auth burst=3 nodelay;
 73	
 74	        proxy_pass http://127.0.0.1:{{ api_host_port }};
 75	        proxy_http_version 1.1;
 76	        proxy_set_header Host $host;
 77	        proxy_set_header X-Real-IP $remote_addr;
 78	        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
 79	        proxy_set_header X-Forwarded-Proto $scheme;
 80	
 81	        proxy_next_upstream error timeout http_502 http_503;
 82	        proxy_next_upstream_timeout 5s;
 83	        proxy_next_upstream_tries 2;
 84	    }
 85	
 86	    # API endpoints (backend)
 87	    location /api/ {
 88	        limit_req zone={{ domain | replace('.', '_') }}_api burst=20 nodelay;
 89	
 90	        proxy_pass http://127.0.0.1:{{ api_host_port }};
 91	        proxy_http_version 1.1;
 92	        proxy_set_header Upgrade $http_upgrade;
 93	        proxy_set_header Connection 'upgrade';
 94	        proxy_set_header Host $host;
 95	        proxy_set_header X-Real-IP $remote_addr;
 96	        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
 97	        proxy_set_header X-Forwarded-Proto $scheme;
 98	        proxy_cache_bypass $http_upgrade;
 99	
100	        # Timeouts
101	        proxy_connect_timeout 60s;
102	        proxy_send_timeout 60s;
103	        proxy_read_timeout 60s;
104	
105	        # Retry on upstream failure during deployments
106	        proxy_next_upstream error timeout http_502 http_503;
107	        proxy_next_upstream_timeout 5s;
108	        proxy_next_upstream_tries 2;
109	    }
110	
111	    # Health check endpoint (no logging)
112	    location /health {
113	        proxy_pass http://127.0.0.1:{{ api_host_port }};
114	        access_log off;
115	    }
116	
117	    # go-draw canvas editor (served by API backend)
118	    location ^~ /draw/ {
119	        proxy_pass http://127.0.0.1:{{ api_host_port }};
120	        proxy_http_version 1.1;
121	        proxy_set_header Host $host;
122	        proxy_set_header X-Real-IP $remote_addr;
123	        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
