import pathlib
p = pathlib.Path('deployment/templates/nginx-ssl.conf.j2')
s = p.read_text()

old = """        # Cache static assets
        location ~* \\.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$ {
            proxy_pass http://127.0.0.1:{{ web_host_port }};
            expires 1y;
            add_header Cache-Control "public, immutable";
        }
    }"""

new = """        # index.html must always be revalidated. It names hash-versioned asset
        # files, and a deploy deletes the previous ones — a cached copy sends the
        # browser after assets that no longer exist, so the tab keeps rendering
        # the old build (or breaks outright) until a manual hard reload.
        location = /index.html {
            proxy_pass http://127.0.0.1:{{ web_host_port }};
            add_header Cache-Control "no-cache, must-revalidate" always;
        }

        # Cache static assets. Safe to keep forever: the filenames are content-hashed.
        location ~* \\.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$ {
            proxy_pass http://127.0.0.1:{{ web_host_port }};
            expires 1y;
            add_header Cache-Control "public, immutable";
        }
    }"""
assert old in s
s = s.replace(old, new, 1)

# The SPA fallback serves index.html for every unknown path, so the no-cache
# header has to apply to those responses too, not just the literal /index.html.
old2 = """    # Frontend (React app via web container)
    location / {
        proxy_pass http://127.0.0.1:{{ web_host_port }};
        proxy_http_version 1.1;"""
new2 = """    # Frontend (React app via web container)
    location / {
        proxy_pass http://127.0.0.1:{{ web_host_port }};
        # Every SPA route resolves to index.html, so these responses carry the
        # same no-cache rule; the hashed assets below opt back into caching.
        add_header Cache-Control "no-cache, must-revalidate" always;
        proxy_http_version 1.1;"""
assert old2 in s
s = s.replace(old2, new2, 1)
p.write_text(s)
print('ok')
