ok
--- taskai head ---
# Nginx configuration for {{ domain }} (with SSL)

# ── Rate limiting ───────────────────────────────────────────────────────────
# The app is request-heavy by design: opening a project fires ~20 API calls,
# and every open tab adds a background refresh every 15s. The old 100r/m
# (1.7 req/s) with burst=20 was below what a single idle tab costs, so normal
# use tripped the limiter.
limit_req_zone $binary_remote_addr zone={{ domain | replace('.', '_') }}_api:10m rate=600r/m;
limit_req_zone $binary_remote_addr zone={{ domain | replace('.', '_') }}_auth:10m rate=30r/m;

# Answer throttled requests with 429, not nginx's default 503. A 503 here is
# indistinguishable from a real outage: it trips the 502/503/504 maintenance
# page (which auto-refreshes and fires another burst of API calls) and matches
# proxy_next_upstream http_503, so each throttled request was also retried
# upstream. 429 does neither.
limit_req_status 429;

# HTTP -> HTTPS redirect
server {
    listen 80;
--- mcp realip ---
deployment/templates/nginx-mcp-ssl.conf.j2:37:    include /etc/nginx/snippets/cloudflare-realip.conf;
deployment/templates/nginx-ssl.conf.j2:43:    include /etc/nginx/snippets/cloudflare-realip.conf;

